"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[746],{553:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-03-logistic-regression</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="bcc9aaf9" class="cell markdown">\n<h1 id="лабораторная-работа--3-логистическая-регрессия-и-оценка-качества">Лабораторная\nработа № 3. Логистическая регрессия и оценка качества</h1>\n<p><strong>Курс:</strong> Классическое машинное обучение, 4 курс\nприкладной математики</p>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Реализовать логистическую регрессию с градиентным спуском, изучить\nметрики классификации и методы визуализации качества.</p>\n<p><strong>Используемые инструменты:</strong> <code>numpy</code>,\n<code>matplotlib</code>, <code>sklearn.metrics</code>,\n<code>sklearn.datasets</code>.</p>\n</div>\n<div id="af80f047" class="cell markdown">\n<h3 id="регламент-сдачи">Регламент сдачи</h3>\n<p>Работа сдаётся в виде этого же ноутбука, дополненного вашим кодом.\nОбязательно:</p>\n<ol>\n<li>Читаемый код с комментариями.</li>\n<li>Визуализации (графики, таблицы).</li>\n<li><strong>Текстовый вывод после каждого задания</strong> — не только\nкод, но и объяснение результата.</li>\n<li>Финальный вывод по работе.</li>\n</ol>\n<p><strong>Критерии оценки:</strong> корректность реализации — 30 %,\nкачество визуализаций и анализа — 20 %, обоснованность выводов — 20 %,\nсравнение с эталонными реализациями — 15 %, оригинальность и\nдополнительная работа — 15 %.</p>\n<blockquote>\n<p>Ячейки, помеченные <code># TODO</code>, нужно заполнить\nсамостоятельно. Ячейки с готовым кодом можно просто выполнить — они\nподготавливают данные и графики.</p>\n</blockquote>\n</div>\n<div id="b3d1292f" class="cell markdown">\n<h2 id="подготовка-окружения">Подготовка окружения</h2>\n</div>\n<div id="5b8ee300" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> seaborn <span class="im">as</span> sns</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="op">%</span>matplotlib inline</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="dv">7</span>, <span class="dv">4</span>),</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a>sns.set_palette(<span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span></span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> load_breast_cancer</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_breast_cancer()</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>X, y <span class="op">=</span> data.data, data.target</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a>X_train, X_test, y_train, y_test <span class="op">=</span> train_test_split(</span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a>    X, y, test_size<span class="op">=</span><span class="fl">0.3</span>, stratify<span class="op">=</span>y, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a>scaler <span class="op">=</span> StandardScaler().fit(X_train)</span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a>X_train_s, X_test_s <span class="op">=</span> scaler.transform(X_train), scaler.transform(X_test)</span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;train:&quot;</span>, X_train_s.shape, <span class="st">&quot; баланс классов:&quot;</span>, np.bincount(y_train))</span></code></pre></div>\n</div>\n<div id="0300e1d6" class="cell markdown">\n<h2 id="задание-1-класс-logisticregressiongd">Задание 1. Класс\n<code>LogisticRegressionGD</code></h2>\n<p>Модель:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>σ</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>T</mi></msup><mi>x</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">p(x) = \\sigma(w^T x)</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi><mo stretchy="false" form="prefix">(</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mstyle displaystyle="true"><mfrac><mn>1</mn><mrow><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mi>−</mi><mi>z</mi></mrow></msup></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">\\sigma(z) = \\dfrac{1}{1 + e^{-z}}</annotation></semantics></math>.</p>\n<p>Функция потерь — бинарная кросс-энтропия:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mo stretchy="false" form="prefix">(</mo><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>−</mi><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mo minsize="180%" maxsize="180%" stretchy="true" form="prefix">[</mo><msub><mi>y</mi><mi>i</mi></msub><mrow><mi>log</mi><mo>⁡</mo></mrow><msub><mi>p</mi><mi>i</mi></msub><mo>+</mo><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mrow><mi>log</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><msub><mi>p</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo minsize="180%" maxsize="180%" stretchy="true" form="postfix">]</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">L(w) = -\\frac{1}{n}\\sum_{i=1}^{n}\\Bigl[y_i \\log p_i + (1 - y_i)\\log(1 - p_i)\\Bigr].</annotation></semantics></math></p>\n<p>Её градиент устроен на удивление просто:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>w</mi></msub><mi>L</mi><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><msup><mi>X</mi><mi>T</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>p</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\\nabla_w L = \\frac{1}{n} X^T (p - y).</annotation></semantics></math></p>\n<p><strong>Численная устойчивость:</strong> при больших\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mi>z</mi><mo stretchy="false" form="prefix">|</mo></mrow><annotation encoding="application/x-tex">|z|</annotation></semantics></math>\nпрямое вычисление\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>e</mi><mrow><mi>−</mi><mi>z</mi></mrow></msup><annotation encoding="application/x-tex">e^{-z}</annotation></semantics></math>\nпереполняется, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>log</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\log(0)</annotation></semantics></math>\nдаёт <code>-inf</code>. Используйте\n<code>np.clip(p, 1e-15, 1 - 1e-15)</code> в функции потерь.</p>\n</div>\n<div id="2392751d" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a><span class="kw">class</span> LogisticRegressionGD:</span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Логистическая регрессия, обучаемая полным градиентным спуском.&quot;&quot;&quot;</span></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>    <span class="kw">def</span> <span class="fu">__init__</span>(<span class="va">self</span>, fit_intercept<span class="op">=</span><span class="va">True</span>):</span>\n<span id="cb2-5"><a href="#cb2-5" aria-hidden="true" tabindex="-1"></a>        <span class="va">self</span>.fit_intercept <span class="op">=</span> fit_intercept</span>\n<span id="cb2-6"><a href="#cb2-6" aria-hidden="true" tabindex="-1"></a>        <span class="va">self</span>.w <span class="op">=</span> <span class="va">None</span></span>\n<span id="cb2-7"><a href="#cb2-7" aria-hidden="true" tabindex="-1"></a>        <span class="va">self</span>.loss_history_ <span class="op">=</span> []</span>\n<span id="cb2-8"><a href="#cb2-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-9"><a href="#cb2-9" aria-hidden="true" tabindex="-1"></a>    <span class="at">@staticmethod</span></span>\n<span id="cb2-10"><a href="#cb2-10" aria-hidden="true" tabindex="-1"></a>    <span class="kw">def</span> _sigmoid(z):</span>\n<span id="cb2-11"><a href="#cb2-11" aria-hidden="true" tabindex="-1"></a>        <span class="co"># </span><span class="al">TODO</span><span class="co">: устойчивая сигмоида (подсказка: scipy.special.expit)</span></span>\n<span id="cb2-12"><a href="#cb2-12" aria-hidden="true" tabindex="-1"></a>        <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb2-13"><a href="#cb2-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-14"><a href="#cb2-14" aria-hidden="true" tabindex="-1"></a>    <span class="kw">def</span> fit(<span class="va">self</span>, X, y, lr<span class="op">=</span><span class="fl">0.01</span>, epochs<span class="op">=</span><span class="dv">1000</span>):</span>\n<span id="cb2-15"><a href="#cb2-15" aria-hidden="true" tabindex="-1"></a>        <span class="co"># </span><span class="al">TODO</span><span class="co">:</span></span>\n<span id="cb2-16"><a href="#cb2-16" aria-hidden="true" tabindex="-1"></a>        <span class="co">#   1. добавьте столбец единиц, инициализируйте w нулями</span></span>\n<span id="cb2-17"><a href="#cb2-17" aria-hidden="true" tabindex="-1"></a>        <span class="co">#   2. на каждой эпохе: p = sigmoid(X @ w); grad = X.T @ (p - y) / n; w -= lr * grad</span></span>\n<span id="cb2-18"><a href="#cb2-18" aria-hidden="true" tabindex="-1"></a>        <span class="co">#   3. сохраняйте значение кросс-энтропии в self.loss_history_</span></span>\n<span id="cb2-19"><a href="#cb2-19" aria-hidden="true" tabindex="-1"></a>        <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb2-20"><a href="#cb2-20" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-21"><a href="#cb2-21" aria-hidden="true" tabindex="-1"></a>    <span class="kw">def</span> predict_proba(<span class="va">self</span>, X):</span>\n<span id="cb2-22"><a href="#cb2-22" aria-hidden="true" tabindex="-1"></a>        <span class="co"># </span><span class="al">TODO</span></span>\n<span id="cb2-23"><a href="#cb2-23" aria-hidden="true" tabindex="-1"></a>        <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb2-24"><a href="#cb2-24" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-25"><a href="#cb2-25" aria-hidden="true" tabindex="-1"></a>    <span class="kw">def</span> predict(<span class="va">self</span>, X, threshold<span class="op">=</span><span class="fl">0.5</span>):</span>\n<span id="cb2-26"><a href="#cb2-26" aria-hidden="true" tabindex="-1"></a>        <span class="co"># </span><span class="al">TODO</span></span>\n<span id="cb2-27"><a href="#cb2-27" aria-hidden="true" tabindex="-1"></a>        <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="063455e3" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите модель и постройте график сходимости loss_history_.</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       Попробуйте lr = 0.001 / 0.01 / 0.1 / 1.0 — нарисуйте все кривые на одном графике.</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       При каком lr спуск расходится?</span></span></code></pre></div>\n</div>\n<div id="11187c2b" class="cell markdown">\n<h2 id="задание-2-сравнение-с-эталоном">Задание 2. Сравнение с\nэталоном</h2>\n<p>Сравните свою реализацию с\n<code>sklearn.linear_model.LogisticRegression</code> по accuracy и по\nзначениям весов.</p>\n</div>\n<div id="aedc670c" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LogisticRegression</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> accuracy_score</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите эталон, сравните accuracy и корреляцию векторов весов.</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       Учтите: sklearn по умолчанию применяет L2-регуляризацию (C=1.0),</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       поэтому для честного сравнения поставьте C очень большим (penalty=None).</span></span></code></pre></div>\n</div>\n<div id="b230e772" class="cell markdown">\n<h2 id="задание-3-roc-кривая-и-auc">Задание 3. ROC-кривая и AUC</h2>\n<p>ROC-кривая — зависимость\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>P</mi><mi>R</mi><mo>=</mo><mstyle displaystyle="true"><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>N</mi></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">TPR = \\dfrac{TP}{TP+FN}</annotation></semantics></math>\nот\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>F</mi><mi>P</mi><mi>R</mi><mo>=</mo><mstyle displaystyle="true"><mfrac><mrow><mi>F</mi><mi>P</mi></mrow><mrow><mi>F</mi><mi>P</mi><mo>+</mo><mi>T</mi><mi>N</mi></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">FPR = \\dfrac{FP}{FP+TN}</annotation></semantics></math>\nпри всех порогах. AUC численно равна вероятности того, что случайный\nположительный объект получит больший скор, чем случайный\nотрицательный.</p>\n</div>\n<div id="759f36e8" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> roc_curve, roc_auc_score</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте ROC-кривые своей модели и эталона на одном графике,</span></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       добавьте диагональ случайного классификатора и подпишите AUC в легенде</span></span></code></pre></div>\n</div>\n<div id="9b815fcf" class="cell markdown">\n<h2 id="задание-4-матрица-ошибок">Задание 4. Матрица ошибок</h2>\n</div>\n<div id="e0e5fa57" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> confusion_matrix, classification_report, ConfusionMatrixDisplay</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте матрицу ошибок и выведите classification_report.</span></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       Прокомментируйте: какая ошибка опаснее в медицинской задаче —</span></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       пропустить злокачественную опухоль (FN) или перестраховаться (FP)?</span></span></code></pre></div>\n</div>\n<div id="480bca9c" class="cell markdown">\n<h2 id="задание-5-precision-и-recall-в-зависимости-от-порога">Задание 5.\nPrecision и Recall в зависимости от порога</h2>\n<p>Постройте график: по оси\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>x</mi><annotation encoding="application/x-tex">x</annotation></semantics></math>\n— порог от 0 до 1, по оси\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>\n— precision, recall и F1. Найдите порог, максимизирующий F1, и сравните\nего с порогом 0.5 по умолчанию.</p>\n</div>\n<div id="932a685f" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> precision_recall_curve, f1_score</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте три кривые на одном графике и отметьте оптимальный порог</span></span></code></pre></div>\n</div>\n<div id="0c83d20c" class="cell markdown">\n<p><strong>Вывод:</strong> <em>почему порог 0.5 не является\nуниверсальным? Как выбирать порог, если цена ошибок FP и FN различается\nв 10 раз?</em></p>\n</div>\n<div id="b5662010" class="cell markdown">\n<h2 id="дополнительное-задание-1-irls-метод-ньютона">Дополнительное\nзадание 1. IRLS (метод Ньютона)</h2>\n<p>Метод Ньютона для логистической регрессии сводится к итеративно\nперевзвешенному МНК:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>w</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo>+</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>=</mo><msup><mi>w</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>+</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>T</mi></msup><mi>S</mi><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>T</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>y</mi><mo>−</mo><mi>p</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mspace width="2.0em"></mspace><mi>S</mi><mo>=</mo><mrow><mi>diag</mi><mo>⁡</mo></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><msub><mi>p</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><msub><mi>p</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">w^{(t+1)} = w^{(t)} + (X^T S X)^{-1} X^T (y - p), \\qquad S = \\operatorname{diag}\\bigl(p_i(1 - p_i)\\bigr).</annotation></semantics></math></p>\n<p>Сравните число итераций до сходимости с градиентным спуском.</p>\n</div>\n<div id="546cf9fd" class="cell code">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте IRLS и постройте кривые сходимости обоих методов на одном графике</span></span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       (по оси x — номер итерации, по оси y — значение функции потерь)</span></span></code></pre></div>\n</div>\n<div id="9db262c4" class="cell markdown">\n<h2 id="дополнительное-задание-2-l_2-регуляризация">Дополнительное\nзадание 2.\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>2</mn></msub><annotation encoding="application/x-tex">L_2</annotation></semantics></math>-регуляризация</h2>\n<p>Добавьте в свою реализацию штраф\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mi>λ</mi><mn>2</mn></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\frac{\\lambda}{2}\\|w\\|^2</annotation></semantics></math>\n(свободный член не штрафуем). Градиент получает слагаемое\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mi>w</mi></mrow><annotation encoding="application/x-tex">\\lambda w</annotation></semantics></math>.\nПокажите, как λ влияет на качество и на сходимость.</p>\n</div>\n<div id="d75da556" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите модель для нескольких lambda, постройте график accuracy(lambda) и норму весов ||w||(lambda)</span></span></code></pre></div>\n</div>\n<div id="605d22a0" class="cell markdown">\n<h2 id="финальный-вывод">Финальный вывод</h2>\n<p><em>Напишите здесь связный вывод по работе (5–10\nпредложений):</em></p>\n<ul>\n<li>какие методы вы применили и почему;</li>\n<li>какие результаты получили в числах;</li>\n<li>где реализация «с нуля» разошлась с эталоном из <code>sklearn</code>\nи в чём причина;</li>\n<li>что бы вы улучшили, будь у вас больше времени.</li>\n</ul>\n</div>\n</body>\n</html>\n'}}]);